begin;
create table if not exists public.matriz_versoes(id bigint generated by default as identity primary key,curso text not null check(curso in ('ADS','EDC')),nome text not null,unique(curso,nome));
create table if not exists public.matriz_versao_disciplinas(id bigint generated by default as identity primary key,versao_id bigint not null references public.matriz_versoes(id),semestre integer not null,disciplina text not null,carga_horaria integer not null,unique(versao_id,disciplina));
create table if not exists public.turma_matriz_versao(turma_id bigint not null references public.turmas(id),curso text not null,versao_id bigint not null references public.matriz_versoes(id),primary key(turma_id,curso));
create table if not exists public.turma_versao_historico(turma_id bigint not null references public.turmas(id),disciplina_id bigint not null references public.matriz_versao_disciplinas(id),status text not null default 'pendente' check(status in ('pendente','em_curso','cumprida','dispensada','nao_ofertar_agora')),periodo_oferta text,observacoes text,primary key(turma_id,disciplina_id));
alter table public.matriz_versoes enable row level security;
drop policy if exists coord on public.matriz_versoes;
create policy coord on public.matriz_versoes for all to authenticated using(public.usuario_e_coordenador()) with check(public.usuario_e_coordenador());
grant select,insert,update,delete on public.matriz_versoes to authenticated;
revoke all on public.matriz_versoes from anon;
alter table public.matriz_versao_disciplinas enable row level security;
drop policy if exists coord on public.matriz_versao_disciplinas;
create policy coord on public.matriz_versao_disciplinas for all to authenticated using(public.usuario_e_coordenador()) with check(public.usuario_e_coordenador());
grant select,insert,update,delete on public.matriz_versao_disciplinas to authenticated;
revoke all on public.matriz_versao_disciplinas from anon;
alter table public.turma_matriz_versao enable row level security;
drop policy if exists coord on public.turma_matriz_versao;
create policy coord on public.turma_matriz_versao for all to authenticated using(public.usuario_e_coordenador()) with check(public.usuario_e_coordenador());
grant select,insert,update,delete on public.turma_matriz_versao to authenticated;
revoke all on public.turma_matriz_versao from anon;
alter table public.turma_versao_historico enable row level security;
drop policy if exists coord on public.turma_versao_historico;
create policy coord on public.turma_versao_historico for all to authenticated using(public.usuario_e_coordenador()) with check(public.usuario_e_coordenador());
grant select,insert,update,delete on public.turma_versao_historico to authenticated;
revoke all on public.turma_versao_historico from anon;
grant usage,select on sequence public.matriz_versoes_id_seq,public.matriz_versao_disciplinas_id_seq to authenticated;
insert into public.matriz_versoes(curso,nome) values('EDC','EDC 2024-1 — matriz antiga') on conflict do nothing;
insert into public.matriz_versao_disciplinas(versao_id,semestre,disciplina,carga_horaria)
select v.id,x.semestre,x.disciplina,x.carga_horaria from public.matriz_versoes v
cross join jsonb_to_recordset('[{"semestre":1,"disciplina":"QUÍMICA GERAL E EXPERIMENTAL","carga_horaria":80},{"semestre":1,"disciplina":"DESENHO TÉCNICO-EXPRESSÃO GRÁFICA","carga_horaria":40},{"semestre":1,"disciplina":"FÍSICA GERAL E EXPERIMENTAL","carga_horaria":80},{"semestre":1,"disciplina":"MATEMÁTICA","carga_horaria":40},{"semestre":1,"disciplina":"HUMANIDADES, CIÊNCIAS SOCIAIS E CIDADANIA","carga_horaria":40},{"semestre":1,"disciplina":"INFORMÁTICA","carga_horaria":40},{"semestre":1,"disciplina":"INTRODUÇÃO À ENGENHARIA","carga_horaria":40},{"semestre":1,"disciplina":"METODOLOGIA CIENTÍFICA E TECNOLÓGICA","carga_horaria":40},{"semestre":2,"disciplina":"CÁLCULO DIFERENCIAL INTEGRAL","carga_horaria":80},{"semestre":2,"disciplina":"FÍSICA GERAL E EXPERIMENTAL APLICADA","carga_horaria":40},{"semestre":2,"disciplina":"DESENHO UNIVERSAL","carga_horaria":40},{"semestre":2,"disciplina":"MECÂNICA DOS SÓLIDOS","carga_horaria":40},{"semestre":2,"disciplina":"CIÊNCIAS DO AMBIENTE","carga_horaria":40},{"semestre":2,"disciplina":"ADMINISTRAÇÃO","carga_horaria":40},{"semestre":2,"disciplina":"ÉTICA E LEGISLAÇÃO","carga_horaria":40},{"semestre":2,"disciplina":"GEOMETRIA ANALÍTICA","carga_horaria":40},{"semestre":2,"disciplina":"ÁLGEBRA LINEAR","carga_horaria":40},{"semestre":3,"disciplina":"ELETRICIDADE","carga_horaria":40},{"semestre":3,"disciplina":"FENÔMENOS DE TRANSPORTES","carga_horaria":80},{"semestre":3,"disciplina":"CIÊNCIA DOS MATERIAIS","carga_horaria":40},{"semestre":3,"disciplina":"PROBABILIDADE E ESTATÍSTICA","carga_horaria":40},{"semestre":3,"disciplina":"ECONOMIA","carga_horaria":40},{"semestre":3,"disciplina":"CÁLCULO DIFERENCIAL INTEGRAL APLICADO","carga_horaria":80},{"semestre":3,"disciplina":"EMPREENDEDORISMO E INOVAÇÃO","carga_horaria":40},{"semestre":3,"disciplina":"ALGORITMOS E PROGRAMAÇÃO","carga_horaria":40},{"semestre":4,"disciplina":"EQUAÇÕES DIFERENCIAIS","carga_horaria":40},{"semestre":4,"disciplina":"HIGIENE E SEGURANÇA DO TRABALHO","carga_horaria":40},{"semestre":4,"disciplina":"CÁLCULO NUMÉRICO","carga_horaria":40},{"semestre":4,"disciplina":"ESTRUTURA DE DADOS I","carga_horaria":80},{"semestre":4,"disciplina":"ALGORITMOS E PROGRAMAÇÃO APLICADA","carga_horaria":40},{"semestre":4,"disciplina":"DISCIPLINA OPTATIVA","carga_horaria":40},{"semestre":4,"disciplina":"TEORIA DOS GRAFOS","carga_horaria":40},{"semestre":4,"disciplina":"SISTEMAS OPERACIONAIS","carga_horaria":80},{"semestre":4,"disciplina":"COMUNICAÇÃO E EXPRESSÃO","carga_horaria":40},{"semestre":5,"disciplina":"ELETROTÉCNICA","carga_horaria":40},{"semestre":5,"disciplina":"ELETRÔNICA DIGITAL","carga_horaria":80},{"semestre":5,"disciplina":"ESTRUTURA DE DADOS II","carga_horaria":80},{"semestre":5,"disciplina":"ARQUITETURA E ORGANIZAÇÃO DE COMPUTADORES","carga_horaria":80},{"semestre":5,"disciplina":"ELETROMAGNETISMO","carga_horaria":80},{"semestre":5,"disciplina":"COMPILADORES","carga_horaria":40},{"semestre":5,"disciplina":"MARKETING","carga_horaria":40},{"semestre":6,"disciplina":"PROGRAMAÇÃO ORIENTADA A OBJETOS","carga_horaria":80},{"semestre":6,"disciplina":"ELETRÔNICA INDUSTRIAL","carga_horaria":80},{"semestre":6,"disciplina":"CIRCUITOS ELÉTRICOS I","carga_horaria":80},{"semestre":6,"disciplina":"ENGENHARIA DE SOFTWARE","carga_horaria":80},{"semestre":6,"disciplina":"BANCO DE DADOS","carga_horaria":80},{"semestre":7,"disciplina":"ANÁLISE E PROJETO DE SISTEMAS ORIENTADOS A OBJETO","carga_horaria":80},{"semestre":7,"disciplina":"GESTÃO DE QUALIDADE","carga_horaria":80},{"semestre":7,"disciplina":"CIRCUITOS ELÉTRICOS II","carga_horaria":80},{"semestre":7,"disciplina":"SISTEMA DE TEMPO REAL","carga_horaria":80},{"semestre":7,"disciplina":"ORGANIZAÇÃO DE EMPRESAS","carga_horaria":40},{"semestre":7,"disciplina":"SINAIS E SISTEMAS","carga_horaria":40},{"semestre":8,"disciplina":"MICROCONTROLADORES E MICROPROCESSADORES","carga_horaria":80},{"semestre":8,"disciplina":"COMPUTAÇÃO GRÁFICA","carga_horaria":80},{"semestre":8,"disciplina":"MULTIMÍDIA, HIPERMÍDIA E TECNOLOGIA WEB","carga_horaria":80},{"semestre":8,"disciplina":"INTERFACE HOMEM-MÁQUINA","carga_horaria":80},{"semestre":8,"disciplina":"SISTEMAS DISTRIBUÍDOS","carga_horaria":80},{"semestre":9,"disciplina":"ROBÓTICA","carga_horaria":80},{"semestre":9,"disciplina":"SISTEMA DE CONTROLE E DE SERVOMECANISMO","carga_horaria":80},{"semestre":9,"disciplina":"TELEPROCESSAMENTO E REDES DE COMPUTADORES","carga_horaria":80},{"semestre":9,"disciplina":"SISTEMAS EMBARCADOS","carga_horaria":80},{"semestre":9,"disciplina":"INTELIGÊNCIA ARTIFICIAL","carga_horaria":80},{"semestre":10,"disciplina":"PLANEJAMENTO E PROJETO","carga_horaria":80},{"semestre":10,"disciplina":"TRABALHO DE CONCLUSÃO DE CURSO","carga_horaria":40},{"semestre":10,"disciplina":"REDES DE COMPUTADORES APLICADA","carga_horaria":40},{"semestre":10,"disciplina":"DESENVOLVIMENTO DE WEB","carga_horaria":80},{"semestre":10,"disciplina":"SISTEMAS DIGITAIS","carga_horaria":80},{"semestre":10,"disciplina":"TÓPICOS ESPECIAIS","carga_horaria":40},{"semestre":10,"disciplina":"REDES INDUSTRIAIS","carga_horaria":40}]'::jsonb) as x(semestre integer,disciplina text,carga_horaria integer)
where v.curso='EDC' and v.nome='EDC 2024-1 — matriz antiga' on conflict do nothing;
do $$begin
if (select count(*) from public.turmas where nome='2024-1' and 'EDC'=any(cursos) and ativa)<>1 then raise exception 'Não foi possível identificar unicamente a turma EDC 2024-1.';end if;end $$;
insert into public.turma_matriz_versao select t.id,'EDC',v.id from public.turmas t cross join public.matriz_versoes v where t.nome='2024-1' and 'EDC'=any(t.cursos) and t.ativa and v.nome='EDC 2024-1 — matriz antiga' and v.curso='EDC' on conflict(turma_id,curso) do update set versao_id=excluded.versao_id;
-- Copia marcações com nomes idênticos. Não apaga nem altera o histórico anterior.
insert into public.turma_versao_historico(turma_id,disciplina_id,status,periodo_oferta,observacoes)
select h.turma_id,d.id,h.status,h.periodo_oferta,h.observacoes from public.turma_disciplinas h join public.turma_matriz_versao tv on tv.turma_id=h.turma_id and tv.curso=h.curso join public.matriz_versao_disciplinas d on d.versao_id=tv.versao_id and upper(trim(d.disciplina))=upper(trim(h.disciplina))
on conflict do nothing;
-- Cumpridas conforme PDF da turma, excluindo o bloco de 2026-2.
-- Optativa I: Comunicação e Expressão é registrada como Comunicação e Expressão;
-- a disciplina optativa genérica permanece pendente.
insert into public.turma_versao_historico(turma_id,disciplina_id,status)
select tv.turma_id,d.id,'cumprida' from public.turma_matriz_versao tv join public.matriz_versoes v on v.id=tv.versao_id join public.matriz_versao_disciplinas d on d.versao_id=v.id
where v.curso='EDC' and v.nome='EDC 2024-1 — matriz antiga'
and d.disciplina in ('QUÍMICA GERAL E EXPERIMENTAL','DESENHO TÉCNICO-EXPRESSÃO GRÁFICA','FÍSICA GERAL E EXPERIMENTAL','MATEMÁTICA','HUMANIDADES, CIÊNCIAS SOCIAIS E CIDADANIA','INFORMÁTICA','INTRODUÇÃO À ENGENHARIA','METODOLOGIA CIENTÍFICA E TECNOLÓGICA','CÁLCULO DIFERENCIAL INTEGRAL','FÍSICA GERAL E EXPERIMENTAL APLICADA','DESENHO UNIVERSAL','MECÂNICA DOS SÓLIDOS','CIÊNCIAS DO AMBIENTE','ADMINISTRAÇÃO','ÉTICA E LEGISLAÇÃO','GEOMETRIA ANALÍTICA','ÁLGEBRA LINEAR','ELETRICIDADE','FENÔMENOS DE TRANSPORTES','CIÊNCIA DOS MATERIAIS','PROBABILIDADE E ESTATÍSTICA','ECONOMIA','CÁLCULO DIFERENCIAL INTEGRAL APLICADO','EMPREENDEDORISMO E INOVAÇÃO','ALGORITMOS E PROGRAMAÇÃO','CÁLCULO NUMÉRICO','ARQUITETURA E ORGANIZAÇÃO DE COMPUTADORES','COMUNICAÇÃO E EXPRESSÃO','ESTRUTURA DE DADOS I','ANÁLISE E PROJETO DE SISTEMAS ORIENTADOS A OBJETO','ENGENHARIA DE SOFTWARE','ESTRUTURA DE DADOS II','ELETRÔNICA INDUSTRIAL','ELETRÔNICA DIGITAL','ELETROTÉCNICA','MARKETING','ELETROMAGNETISMO')
on conflict(turma_id,disciplina_id) do update set status='cumprida';
commit;
